import{_ as n,C as e,o as r,c as l,j as d,a as s,G as o,a3 as h}from"./chunks/framework.Bvm_liKL.js";const f=JSON.parse('{"title":"PowerPoint Guide","description":"A complete guide for ICC-CE integration with PowerPoint/WPS, including slideshow annotation, ink saving, time capsule, and more","frontmatter":{"title":"PowerPoint Guide","description":"A complete guide for ICC-CE integration with PowerPoint/WPS, including slideshow annotation, ink saving, time capsule, and more"},"headers":[],"relativePath":"en/guide/ppt-guide.md","filePath":"en/guide/ppt-guide.md"}'),g={name:"en/guide/ppt-guide.md"};function u(c,t,p,b,m,w){const i=e("ArticleMetadata"),a=e("UnderConstruction");return r(),l("div",null,[t[0]||(t[0]=d("h1",{id:"powerpoint-guide",tabindex:"-1"},[s("PowerPoint Guide "),d("a",{class:"header-anchor",href:"#powerpoint-guide","aria-label":'Permalink to "PowerPoint Guide"'},"​")],-1)),o(i),o(a),t[1]||(t[1]=h('<h2 id="ppt-integration-mode" tabindex="-1">PPT Integration Mode <a class="header-anchor" href="#ppt-integration-mode" aria-label="Permalink to &quot;PPT Integration Mode&quot;">​</a></h2><p>Automatically activates when PowerPoint enters slideshow mode — no manual operation needed. In this mode:</p><ul><li>Page navigation buttons appear on the toolbar for slideshow control</li><li>Ink written on slides is automatically saved per page</li><li>Annotations are restored automatically when returning to previously annotated pages</li><li>After the slideshow ends, you can return to normal mode to continue editing</li></ul><blockquote><p>Integration not working? Check: Is PowerPoint activated? Is it in protected view (read-only)? Is PowerPoint running as administrator while ICC-CE is not elevated?</p></blockquote><h2 id="basic-integration-settings" tabindex="-1">Basic Integration Settings <a class="header-anchor" href="#basic-integration-settings" aria-label="Permalink to &quot;Basic Integration Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Enable PPT Integration</td><td>Toggle</td><td>On</td><td>Auto-enable annotation when PowerPoint slideshow is detected</td></tr><tr><td>Integration Mode</td><td>Select</td><td>COM</td><td>COM / ROT / Agent</td></tr><tr><td>Enable WPS Support</td><td>Toggle</td><td>Off</td><td>Enable WPS Presentation integration</td></tr><tr><td>Close WPS Process</td><td>Toggle</td><td>On</td><td>Auto-close lingering WPS processes</td></tr><tr><td>Smart Mode</td><td>Toggle</td><td>Off</td><td>Intelligently detect and switch to optimal integration mode</td></tr></tbody></table><h2 id="slideshow-control" tabindex="-1">Slideshow Control <a class="header-anchor" href="#slideshow-control" aria-label="Permalink to &quot;Slideshow Control&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Show PPT Buttons</td><td>Toggle</td><td>On</td><td>Show page navigation controls during slideshow</td></tr><tr><td>Page Number Clickable</td><td>Toggle</td><td>On</td><td>Click page number to jump directly</td></tr><tr><td>Long Press for Page Navigation</td><td>Toggle</td><td>On</td><td>Long press to continuously flip pages</td></tr><tr><td>Enhanced Preview</td><td>Toggle</td><td>Off</td><td>Enable enhanced slide preview</td></tr><tr><td>Enhanced Preview Loading Animation</td><td>Toggle</td><td>On</td><td>Show loading animation during preview</td></tr><tr><td>Show Canvas on New Slide</td><td>Toggle</td><td>Off</td><td>Auto-show canvas when switching to a new slide</td></tr><tr><td>Two-Finger Gesture Control During Slideshow</td><td>Toggle</td><td>Off</td><td>Use two-finger gestures for page navigation during slideshow</td></tr></tbody></table><h2 id="ink-saving" tabindex="-1">Ink Saving <a class="header-anchor" href="#ink-saving" aria-label="Permalink to &quot;Ink Saving&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Auto-Save Ink During Slideshow</td><td>Toggle</td><td>On</td><td>Auto-save all ink to file when slideshow ends</td></tr><tr><td>Auto-Screenshot During Slideshow</td><td>Toggle</td><td>Off</td><td>Auto-screenshot on clear screen or slide change</td></tr><tr><td>Auto-Save Time Capsule During Slideshow</td><td>Toggle</td><td>On</td><td>Auto-save ink timestamp data for playback</td></tr><tr><td>Auto-Append Extension on Save</td><td>Toggle</td><td>On</td><td>Auto-add file extension when saving</td></tr><tr><td>Auto-Rename on Save</td><td>Toggle</td><td>Off</td><td>Auto-generate file name to avoid overwriting</td></tr><tr><td>Save Location</td><td>Directory</td><td>Default</td><td>Custom ink file save path</td></tr><tr><td>Ink-Saving Mode</td><td>Toggle</td><td>Off</td><td>Save ink in more compact format to reduce file size</td></tr></tbody></table><h2 id="slideshow-toolbar" tabindex="-1">Slideshow Toolbar <a class="header-anchor" href="#slideshow-toolbar" aria-label="Permalink to &quot;Slideshow Toolbar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Auto-Hide Toolbar Delay</td><td>Time</td><td>30 seconds</td><td>Auto-hide toolbar after inactivity during slideshow</td></tr><tr><td>Enable Rounded PPT Toolbar</td><td>Toggle</td><td>On</td><td>Use rounded style toolbar during slideshow</td></tr><tr><td>Show Toolbar During Slideshow</td><td>Toggle</td><td>On</td><td>Show floating toolbar during slideshow</td></tr><tr><td>Show Collapse Button During Slideshow</td><td>Toggle</td><td>On</td><td>Show collapse button in slideshow mode</td></tr></tbody></table><h2 id="time-capsule" tabindex="-1">Time Capsule <a class="header-anchor" href="#time-capsule" aria-label="Permalink to &quot;Time Capsule&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Time Capsule Auto-Play</td><td>Toggle</td><td>Off</td><td>Auto-play when opening a time capsule</td></tr><tr><td>Time Capsule Auto-Export</td><td>Toggle</td><td>Off</td><td>Auto-export when closing a time capsule</td></tr><tr><td>Time Capsule Auto-Export Format</td><td>Select</td><td>PNG</td><td>PNG / GIF / MP4</td></tr><tr><td>Time Capsule GIF Frame Rate</td><td>Number</td><td>10</td><td>Frame rate for GIF export</td></tr><tr><td>Time Capsule Timeline Scale</td><td>Slider</td><td>1.0</td><td>Timeline display zoom ratio</td></tr><tr><td>Time Capsule Auto-Play Speed</td><td>Slider</td><td>1.0</td><td>Auto-play speed multiplier</td></tr></tbody></table><h2 id="other-settings" tabindex="-1">Other Settings <a class="header-anchor" href="#other-settings" aria-label="Permalink to &quot;Other Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Enable PPT End Detection</td><td>Toggle</td><td>On</td><td>Auto-detect slideshow end and exit annotation mode</td></tr><tr><td>Auto-Exit on Slideshow End</td><td>Toggle</td><td>Off</td><td>Auto-exit software when slideshow ends</td></tr></tbody></table><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ol><li>Make sure PowerPoint is activated, not in protected view / read-only mode</li><li>Check that PPT integration is enabled in ICC-CE settings</li><li>Check if PowerPoint is running as administrator while ICC-CE is not elevated</li><li>If using WPS simultaneously, try disabling WPS support or enabling Smart Mode</li><li>Try switching integration modes (COM / ROT / Agent)</li></ol>',18))])}const T=n(g,[["render",u]]);export{f as __pageData,T as default};
